await call('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-motion',value:'reduce'}]});
for (const id of ['c15','c21','c22']) {
  await route('cards/'+id); await ready(`getFilteredCards()[state.index].id==='${id}'`);
  await evaluate('toggleAnswer()');
  await check('published card '+id,`state.revealed && document.getElementById('card-short-en').textContent===CARDS.find(c=>c.id==='${id}').shortEN && document.getElementById('card-translation').textContent.includes(CARDS.find(c=>c.id==='${id}').shortRU)`);
}
for (const id of ['q7','q8','q10','q12','q13','q16','q19']) {
  await route('quiz/'+id);
  await evaluate(`document.querySelectorAll('input[name=${id}]')[QUIZ_QUESTIONS.find(q=>q.id==='${id}').correct].click()`);
  await check('published quiz '+id,`document.getElementById('${id}-title-res').textContent.includes('Верно') && document.getElementById('${id}-exp-en').textContent===QUIZ_QUESTIONS.find(q=>q.id==='${id}').speechEN`);
}
for (const width of [390,1440]) {
  await call('Emulation.setDeviceMetricsOverride',{width,height:1000,deviceScaleFactor:1,mobile:false});
  await route('cards/c22');await ready("getFilteredCards()[state.index].id==='c22'");
  await evaluate("toggleAnswer();document.querySelectorAll('#card-answer-box details').forEach(d=>d.open=true);document.getElementById('card-code').scrollIntoView();window.scrollBy(0,-140)");
  await ready("getComputedStyle(document.getElementById('card-answer-box')).opacity==='1'");
  await check('published card expanded '+width,'document.documentElement.scrollWidth<=innerWidth');
  const shot=await call('Page.captureScreenshot',{format:'png'});writeFileSync(`/private/tmp/live20-card-${width}.png`,Buffer.from(shot.data,'base64'));
  await route('quiz/q19');await evaluate("document.querySelectorAll('#q19 details').forEach(d=>d.open=true);document.getElementById('q19-result').scrollIntoView();window.scrollBy(0,-140)");
  await check('published quiz expanded '+width,'document.documentElement.scrollWidth<=innerWidth');
  const quizShot=await call('Page.captureScreenshot',{format:'png'});writeFileSync(`/private/tmp/live20-quiz-${width}.png`,Buffer.from(quizShot.data,'base64'));
}
